import DeviceInfo from 'react-native-device-info';

type Policy = { latest: string; minSupported: string };
export type UpdateMode = 'none' | 'soft' | 'force';

function isOlder(installed: string, target: string): boolean {
  return installed < target;
}

export async function checkForUpdate(fetchPolicy: () => Promise<Policy>): Promise<UpdateMode> {
  const installed = DeviceInfo.getVersion();
  let policy: Policy;
  try {
    policy = await fetchPolicy();
  } catch {
    return 'none';
  }
  if (isOlder(installed, policy.minSupported)) return 'force';
  return isOlder(installed, policy.latest) ? 'soft' : 'none';
}
